<?php /** @var array $sessions; int $toValidate; string $btab, $bbase */ echo view('pro/bars/_nav', compact('btab', 'bbase')); ?>
<?php if ($toValidate): ?><div class="notice warn mb"><b><?= (int)$toValidate ?> clôture(s) à valider.</b> Vérifie l'écart de chaque Z, ajoute une explication si besoin, puis valide : les clôtures validées sont prêtes pour la comptabilité.</div><?php endif; ?>
<p class="muted lead-sm">Chaque caisse s'ouvre avec un fond de caisse et se clôture en comptant les espèces : l'écart avec le montant attendu est calculé automatiquement. Les remises en banque (espèces retirées en cours de soirée) et les apports sont saisis sur la caisse.</p>
<?php foreach ($sessions as $s): $t = $s['t']; $open = !$s['closed_at']; $gap = $s['counted_cash'] !== null ? (int)$s['counted_cash'] - (int)$s['expected_cash'] : null; ?>
  <div class="card z-card<?= $open ? ' open' : '' ?>">
    <div class="z-head"><div class="grow"><b><?= $open ? 'En cours' : 'Z' . (int)$s['z_number'] ?> · <?= e($s['bar']) ?></b> <?= $open ? '<span class="badge green">ouverte</span>' : ($s['validated_at'] ? '<span class="badge green">validée</span>' : '<span class="badge orange">à valider</span>') ?><br>
      <small class="muted"><?= $s['device'] ? e((string)$s['device']) . ' · ' : '' ?><?= e(date('d/m H:i', strtotime($s['opened_at']))) ?><?= $s['opener'] ? ' (' . e($s['opener']) . ')' : '' ?><?= $s['closed_at'] ? ' → ' . e(date('d/m H:i', strtotime($s['closed_at']))) . ($s['closer'] ? ' (' . e($s['closer']) . ')' : '') : '' ?></small></div>
      <a class="btn btn-sm btn-light" target="_blank" href="<?= url($bbase . '/caisses', ['z' => $s['id']]) ?>"><?= $open ? 'Ticket X (PDF)' : 'Ticket Z (PDF)' ?></a></div>
    <div class="z-grid">
      <div><span>Cashless</span><b><?= e(money((int)($t['methods']['cashless']['total'] ?? 0))) ?></b></div>
      <div><span>Carte</span><b><?= e(money((int)($t['methods']['card']['total'] ?? 0))) ?></b></div>
      <div><span>Espèces</span><b><?= e(money((int)($t['methods']['cash']['total'] ?? 0))) ?></b></div>
      <div><span>Offert</span><b><?= e(money((int)$t['offered'])) ?></b></div>
      <div><span>Espèces attendues</span><b><?= e(money((int)$t['expected_cash'])) ?></b><small class="muted">fond <?= e(money((int)$t['float'])) ?> · banque −<?= e(money((int)$t['moves']['drop'])) ?></small></div>
      <div class="<?= $gap === null ? '' : ($gap === 0 ? 'ok' : 'ko') ?>"><span>Compté</span><b><?= $s['counted_cash'] !== null ? e(money((int)$s['counted_cash'])) : '—' ?></b><?= $gap !== null ? '<small>écart ' . ($gap > 0 ? '+' : '') . e(money($gap)) . '</small>' : '' ?></div>
    </div>
    <?php if ($s['tabs']): ?><p class="muted"><small><?= (int)$s['tabs']['n'] ?> addition(s) ouverte(s) sur ce point de vente, <?= e(money((int)$s['tabs']['t'])) ?> pas encore encaissés.</small></p><?php endif; ?>
    <?php if (!empty($t['staff'])): ?><details><summary class="linklike">Par serveur (<?= count($t['staff']) ?>)</summary><?php foreach ($t['staff'] as $n => $x): ?><div class="list-item"><span class="grow"><?= e($n) ?><br><small class="muted"><?= (int)$x['n'] ?> vente(s) · espèces <?= e(money((int)$x['cash'])) ?><?= $x['offered'] ? ' · offert ' . e(money((int)$x['offered'])) : '' ?></small></span><b><?= e(money((int)$x['total'])) ?></b></div><?php endforeach; ?></details><?php endif; ?>
    <?php if ($s['float_json'] || $s['count_json']): ?><details><summary class="linklike">Comptage billets et pièces</summary><p class="muted"><small><?= $s['float_json'] ? 'Fond : ' . e(bars_count_txt($s['float_json'])) . '<br>' : '' ?><?= $s['count_json'] ? 'Clôture : ' . e(bars_count_txt($s['count_json'])) : '' ?></small></p></details><?php endif; ?>
    <?php if ($s['moves']): ?><details><summary class="linklike">Mouvements d'espèces (<?= count($s['moves']) ?>)</summary><?php foreach ($s['moves'] as $m): ?><div class="list-item"><span class="grow"><?= $m['kind'] === 'drop' ? 'Remise en banque' : 'Apport' ?><?= $m['note'] ? ' · ' . e($m['note']) : '' ?><br><small class="muted"><?= e(date('H:i', strtotime($m['created_at']))) ?> <?= e((string)$m['staff']) ?></small></span><b><?= $m['kind'] === 'drop' ? '−' : '+' ?><?= e(money((int)$m['amount'])) ?></b></div><?php endforeach; ?></details><?php endif; ?>
    <?php if (!$open): ?><form method="post" class="row mt z-validate"><?= csrf_field() ?><input type="hidden" name="action" value="validate"><input type="hidden" name="session_id" value="<?= (int)$s['id'] ?>">
      <?php if ($s['validated_at']): ?><small class="muted grow">Validée <?= e(fr_date($s['validated_at'])) ?><?= $s['validator'] ? ' par ' . e($s['validator']) : '' ?><?= $s['validation_note'] ? ' : « ' . e($s['validation_note']) . ' »' : '' ?></small><button class="btn btn-sm btn-ghost">Retirer la validation</button>
      <?php else: ?><input name="note" class="grow" placeholder="<?= $gap ? 'Explication de l\'écart (erreur de rendu, pourboire…)' : 'Commentaire (facultatif)' ?>"><button class="btn btn-sm">Valider la clôture</button><?php endif; ?></form><?php endif; ?>
    <?php if ($open): ?><details class="mt"><summary class="linklike">Clôturer à distance</summary><form method="post" class="row mt"><?= csrf_field() ?><input type="hidden" name="action" value="force_close"><input type="hidden" name="session_id" value="<?= (int)$s['id'] ?>"><div class="input-suffix u-mw200"><input name="counted" inputmode="decimal" placeholder="Espèces comptées"><span>€</span></div><button class="btn btn-sm" data-confirm="Clôturer cette caisse ?">Clôturer</button></form></details><?php endif; ?>
  </div>
<?php endforeach; ?>
<?php if (!$sessions): ?><div class="card empty">Aucune caisse ouverte pour l'instant. Sur l'application, « Ouvrir la caisse » demande le fond de caisse.</div><?php endif; ?>
